+import assert from "node:assert/strict";
+import { readdirSync, readFileSync } from "node:fs";
+import path from "node:path";
+import test from "node:test";
+import { fileURLToPath } from "node:url";
+
+const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
+const read = (relativePath) => readFileSync(path.join(root, relativePath), "utf8");
+
+function walk(relativeDirectory) {
+  const directory = path.join(root, relativeDirectory);
+  return readdirSync(directory, { withFileTypes: true }).flatMap((entry) => {
+    const relativePath = path.join(relativeDirectory, entry.name);
+    return entry.isDirectory() ? walk(relativePath) : [relativePath];
+  });
+}
+
+test("light and dark themes expose the reset semantic contract", () => {
+  const css = read("app/globals.css");
+  for (const selector of [":root", 'html[data-theme="light"]', 'html[data-theme="dark"]']) assert.match(css, new RegExp(selector.replace(/[\[\]]/g, "\\$&")));
+  for (const token of ["surface-page", "surface-interactive", "surface-overlay", "text-primary", "text-secondary", "text-tertiary", "action-primary", "action-secondary", "selection", "line", "focus", "disabled-surface", "disabled-text"]) {
+    assert.ok(css.split(`--${token}:`).length >= 3, `${token} must exist in light and dark themes`);
+  }
+  assert.doesNotMatch(css, /linear-gradient|radial-gradient/);
+});
+
+test("the dark theme avoids pure black and uses clay for primary actions", () => {
+  const css = read("app/globals.css");
+  const dark = css.slice(css.indexOf('html[data-theme="dark"]'), css.indexOf("@theme inline"));
+  assert.match(dark, /--surface-page: #222622/);
+  assert.match(dark, /--action-primary: #c78c70/);
+  assert.match(dark, /--selection: #3c5244/);
+  assert.doesNotMatch(dark, /#000000|#000\b/);
+});
+
+test("component source contains no one-off hexadecimal colors or gradients", () => {
+  const files = walk("app").filter((file) => /\.(?:tsx|ts|css)$/.test(file) && file !== path.join("app", "globals.css") && file !== path.join("app", "lib", "vet-brief", "pdf-theme.ts"));
+  const failures = files.filter((file) => /#[0-9a-f]{3,8}|(?:linear|radial)-gradient/i.test(read(file)));
+  assert.deepEqual(failures, [], `Unexpected component colors: ${failures.join(", ")}`);
+});
+
+test("theme persistence remains cookie-backed and controls consume semantic roles", () => {
+  const appearance = read("app/lib/appearance.ts");
+  const layout = read("app/layout.tsx");
+  const header = read("app/components/app-header.tsx");
+  const primitives = read("app/components/product-primitives.tsx");
+  assert.match(appearance, /APPEARANCE_MODE_COOKIE = "furvise-mode"/);
+  assert.match(appearance, /localStorage\.getItem\(THEME_MODE_STORAGE_KEY\)/);
+  assert.match(layout, /const cookieStore = await cookies\(\)/);
+  assert.match(layout, /data-theme=\{mode\}/);
+  assert.match(header, /var\(--action-primary\)/);
+  assert.match(primitives, /var\(--focus\)|var\(--line-strong\)|var\(--disabled-surface\)/);
+  assert.match(read("app/globals.css"), /:focus-visible[\s\S]*var\(--focus\)/);
+});
*** End Patch";
text(await tools.apply_patch(patch));

